import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
        if not data or not isinstance(data, list):
            raise ValueError("Invalid or empty JSON data")
        processed_data = []
        for entry in data:
            if not isinstance(entry.get("Country"), str) or not isinstance(entry.get("Population"), (int, float)):
                raise ValueError("Invalid data format")
            population = entry["Population"]
            if population < 0:
                raise ValueError("Population cannot be negative")
            processed_data.append({"Country": entry["Country"], "Population": math.floor(population)})
        df = pd.DataFrame(processed_data, columns=["Country", "Population"])
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
        return output_path, df
    except ValueError as ve:
        raise ve
    except Exception as e:
        raise IOError("Failed to write the file") from e
